就是求 $a^x\equiv b\ (\bmod\ p)$ 的一个算法，复杂度 $\mathcal{O}(\sqrt{p})$。

开局分成两坨，设 $s=\lceil \sqrt {p} \rceil$（平衡复杂度），令 $x=ps-y$。

所以原方程就可以写成 $a^{ps}\equiv b\cdot a^y \ (\bmod\ p)$。

然后就显而易见了，两边直接用 map 找一下就行了（或者手写hash也可以的）

具体代码：

```cpp
int BSGS(int a,int b,int p)
{
    // solving: a^x===b (mod p)
    if(a==1 && b==1) return 0;
    if(a==b) return 1;
    if(a==0) return (b==1?0:-1);
    map<int,int> mp;
    int s=ceil(sqrt(p));
    // cout<<s<<'\n';
    int base=1;
    for(int i=1;i<=s;i++)
    {
        base=base*a%p;
        mp[b*base%p]=i+1;
    }
    int base2=base;
    for(int i=1;i<=s;i++)
    {
        if(mp.count(base2)) return i*s-mp[base2]+1;
        base2=base2*base%p;
        // cout<<base2<<'\n';
    }
    return -1;
}
