        else if(op==2) umin(1,1,n,l,r,k);
        else if(op==3) cout<<qsum(1,1,n,l,r)<<'\n';
        else if(op==4) cout<<qmax(1,1,n,l,r)<<'\n';
        else cout<<qhis(1,1,n,l,r)<<'\n';
    }
